mapper.select:
SELECT  FROM iam.tenant_entitlements
WHERE tenant_id = #{tenantId}
AND resource_code > #{afterResourceCode}
ORDER BY resource_code ASC LIMIT #{fetchSize}

mapper.update:
UPDATE iam.tenant_entitlements SET
    status = #{status},
    revision = revision + 1,
    granted_at = CASE WHEN #{status} = 'active' THEN now() ELSE granted_at END,
    revoked_at = CASE WHEN #{status} = 'revoked' THEN now() ELSE revoked_at END,
    updated_by = #{updatedBy}
WHERE tenant_id = #{tenantId} AND resource_code = #{resourceCode}
  AND revision = #{expectedRevision}
